import sys
from math import factorial
from collections import Counter

def compute_rank(N):
    digits = list(N)
    n = len(digits)
    rank = 1
    freq = Counter(digits)

    for i in range(n):
        for d in map(str, range(int(digits[i]))):
            if d in freq and freq[d] > 0:
                remaining_freq = freq.copy()
                remaining_freq[d] -= 1
                if remaining_freq[d] == 0:
